// FreeLang VM Runtime Phase 3: Memory Management & Garbage Collection
// 목표: 메모리 할당, 해제, Mark-and-Sweep GC, 메모리 풀 관리, 누수 탐지
// 구현: 200줄 FreeLang
// 테스트: 4개 무관용 테스트

// ============================================================================
// 상수 정의
// ============================================================================

const MEMORY_SIZE: i32 = 65536;           // 64KB 메모리
const STACK_SIZE: i32 = 20480;            // 20KB 스택 (0x0000 ~ 0x5000)
const HEAP_SIZE: i32 = 44544;             // 44KB 힙 (0x5000 ~ 0xFE00)
const MAX_OBJECTS: i32 = 1000;            // 최대 객체 수

// ============================================================================
// 구조체: 메모리 할당자 (Allocator)
// ============================================================================

struct MemoryAllocator {
  heap_start: i32,
  heap_end: i32,
  heap_used: i32,
  num_objects: i32,
  allocations: [i32; 1000],  // 할당된 블록의 시작 주소
  sizes: [i32; 1000],         // 각 블록의 크기
  marked: [bool; 1000],       // GC 표시 플래그
  ref_count: [i32; 1000],     // 참조 카운트
  stats_allocated: i32,       // 누적 할당 크기
  stats_freed: i32,           // 누적 해제 크기
  stats_gc_runs: i32,         // GC 실행 횟수
}

fn MemoryAllocator__new() -> MemoryAllocator {
  return MemoryAllocator {
    heap_start: 20480,        // 0x5000
    heap_end: 65280,          // 0xFE00 (예약: 256B)
    heap_used: 0,
    num_objects: 0,
    allocations: [0; 1000],
    sizes: [0; 1000],
    marked: [false; 1000],
    ref_count: [0; 1000],
    stats_allocated: 0,
    stats_freed: 0,
    stats_gc_runs: 0,
  };
}

// ============================================================================
// 메모리 할당 (malloc)
// ============================================================================

fn MemoryAllocator__malloc(allocator: MemoryAllocator, size: i32) -> i32 {
  // 메모리 블록 찾기
  if allocator.num_objects >= 1000 {
    return -1;  // 오류: 객체 수 초과
  }

  // 충분한 힙 공간 확인
  if allocator.heap_used + size > 44544 {
    return -2;  // 오류: 힙 메모리 부족
  }

  // 할당 주소 계산
  let addr: i32 = allocator.heap_start + allocator.heap_used;
  let obj_idx: i32 = allocator.num_objects;

  // 할당 정보 기록
  allocator.allocations[obj_idx] = addr;
  allocator.sizes[obj_idx] = size;
  allocator.marked[obj_idx] = false;
  allocator.ref_count[obj_idx] = 1;

  // 통계 업데이트
  allocator.heap_used = allocator.heap_used + size;
  allocator.num_objects = allocator.num_objects + 1;
  allocator.stats_allocated = allocator.stats_allocated + size;

  return addr;
}

// ============================================================================
// 메모리 해제 (free)
// ============================================================================

fn MemoryAllocator__free(allocator: MemoryAllocator, addr: i32) -> bool {
  // 주소에 해당하는 객체 찾기
  let i: i32 = 0;
  while i < allocator.num_objects {
    if allocator.allocations[i] == addr {
      // 객체 찾음
      let size: i32 = allocator.sizes[i];

      // 통계 업데이트
      allocator.stats_freed = allocator.stats_freed + size;

      // 마지막 객체가 아니면 스왑
      if i < allocator.num_objects - 1 {
        let last: i32 = allocator.num_objects - 1;
        allocator.allocations[i] = allocator.allocations[last];
        allocator.sizes[i] = allocator.sizes[last];
        allocator.marked[i] = allocator.marked[last];
        allocator.ref_count[i] = allocator.ref_count[last];
      }

      allocator.num_objects = allocator.num_objects - 1;
      return true;
    }
    i = i + 1;
  }

  return false;  // 주소를 찾을 수 없음
}

// ============================================================================
// Mark-and-Sweep GC
// ============================================================================

fn MemoryAllocator__mark_phase(allocator: MemoryAllocator, root_addr: i32) {
  // Mark phase: 루트에서 도달 가능한 모든 객체를 표시
  let i: i32 = 0;
  while i < allocator.num_objects {
    allocator.marked[i] = false;
    i = i + 1;
  }

  // 루트 객체 찾기 및 표시
  i = 0;
  while i < allocator.num_objects {
    if allocator.allocations[i] == root_addr {
      allocator.marked[i] = true;
      break;
    }
    i = i + 1;
  }

  // 참조 카운트 > 0인 객체도 표시 (고정 객체)
  i = 0;
  while i < allocator.num_objects {
    if allocator.ref_count[i] > 0 {
      allocator.marked[i] = true;
    }
    i = i + 1;
  }
}

fn MemoryAllocator__sweep_phase(allocator: MemoryAllocator) -> i32 {
  // Sweep phase: 표시되지 않은 객체 해제
  let i: i32 = 0;
  let freed_count: i32 = 0;

  while i < allocator.num_objects {
    if !allocator.marked[i] {
      // 표시되지 않은 객체 해제
      let freed_size: i32 = allocator.sizes[i];
      allocator.stats_freed = allocator.stats_freed + freed_size;

      // 마지막 객체와 스왑
      if i < allocator.num_objects - 1 {
        let last: i32 = allocator.num_objects - 1;
        allocator.allocations[i] = allocator.allocations[last];
        allocator.sizes[i] = allocator.sizes[last];
        allocator.marked[i] = allocator.marked[last];
        allocator.ref_count[i] = allocator.ref_count[last];
      }

      allocator.num_objects = allocator.num_objects - 1;
      freed_count = freed_count + 1;

      // 인덱스를 증가시키지 않음 (같은 위치에서 다시 확인)
    } else {
      i = i + 1;
    }
  }

  return freed_count;
}

fn MemoryAllocator__gc_trigger(allocator: MemoryAllocator, root_addr: i32) -> bool {
  // GC 트리거 (메모리 부족 또는 임계값 초과)
  if allocator.heap_used > (44544 * 80) / 100 {
    // Mark phase
    MemoryAllocator__mark_phase(allocator, root_addr);

    // Sweep phase
    let freed: i32 = MemoryAllocator__sweep_phase(allocator);

    // 통계 업데이트
    allocator.stats_gc_runs = allocator.stats_gc_runs + 1;

    return true;
  }

  return false;
}

// ============================================================================
// 메모리 풀 (Object Pool)
// ============================================================================

struct MemoryPool {
  object_size: i32,
  num_objects: i32,
  available: [bool; 100],
  objects: [i32; 100],
}

fn MemoryPool__new(object_size: i32, num_objects: i32) -> MemoryPool {
  return MemoryPool {
    object_size: object_size,
    num_objects: num_objects,
    available: [true; 100],
    objects: [0; 100],
  };
}

fn MemoryPool__acquire(pool: MemoryPool, allocator: MemoryAllocator) -> i32 {
  // 사용 가능한 객체 찾기
  let i: i32 = 0;
  while i < pool.num_objects {
    if pool.available[i] {
      pool.available[i] = false;
      return i;  // 객체 인덱스 반환
    }
    i = i + 1;
  }

  return -1;  // 사용 가능한 객체 없음
}

fn MemoryPool__release(pool: MemoryPool, index: i32) -> bool {
  if index >= 0 && index < pool.num_objects {
    pool.available[index] = true;
    return true;
  }

  return false;
}

// ============================================================================
// 누수 탐지 (Leak Detection)
// ============================================================================

fn MemoryAllocator__detect_leaks(allocator: MemoryAllocator) -> i32 {
  // 접근 불가능한 객체 (누수) 개수 반환
  let leak_count: i32 = 0;
  let i: i32 = 0;

  while i < allocator.num_objects {
    if allocator.ref_count[i] == 0 && !allocator.marked[i] {
      leak_count = leak_count + 1;
    }
    i = i + 1;
  }

  return leak_count;
}

fn MemoryAllocator__get_leak_memory(allocator: MemoryAllocator) -> i32 {
  // 누수된 메모리의 총 크기 반환
  let leak_size: i32 = 0;
  let i: i32 = 0;

  while i < allocator.num_objects {
    if allocator.ref_count[i] == 0 && !allocator.marked[i] {
      leak_size = leak_size + allocator.sizes[i];
    }
    i = i + 1;
  }

  return leak_size;
}

// ============================================================================
// 할당 통계 (Allocation Statistics)
// ============================================================================

struct MemoryStats {
  total_allocated: i32,
  total_freed: i32,
  current_usage: i32,
  num_objects: i32,
  gc_runs: i32,
  fragmentation_ratio: f32,
}

fn MemoryAllocator__get_stats(allocator: MemoryAllocator) -> MemoryStats {
  let current_usage: i32 = allocator.heap_used;
  let fragmentation_ratio: f32 = 0.0;

  if allocator.stats_allocated > 0 {
    fragmentation_ratio = (allocator.stats_allocated - allocator.stats_freed) as f32 /
                          allocator.stats_allocated as f32;
  }

  return MemoryStats {
    total_allocated: allocator.stats_allocated,
    total_freed: allocator.stats_freed,
    current_usage: current_usage,
    num_objects: allocator.num_objects,
    gc_runs: allocator.stats_gc_runs,
    fragmentation_ratio: fragmentation_ratio,
  };
}

fn MemoryAllocator__print_stats(allocator: MemoryAllocator) {
  let stats: MemoryStats = MemoryAllocator__get_stats(allocator);

  println("=== Memory Statistics ===");
  print("Total Allocated: ");
  println(stats.total_allocated);
  print("Total Freed: ");
  println(stats.total_freed);
  print("Current Usage: ");
  println(stats.current_usage);
  print("Number of Objects: ");
  println(stats.num_objects);
  print("GC Runs: ");
  println(stats.gc_runs);
  print("Fragmentation: ");
  println(stats.fragmentation_ratio);
}

// FreeLang VM Runtime Phase 3: Memory Management Tests
// 4개 무관용 테스트

// ============================================================================
// Test T1: 기본 할당/해제 (Allocation & Deallocation)
// ============================================================================

fn test_T1_allocation_deallocation() -> bool {
  // 메모리 할당자 생성
  let allocator: MemoryAllocator = MemoryAllocator__new();
  let initial_objects: i32 = allocator.num_objects;

  // 256바이트 블록 할당
  let addr1: i32 = MemoryAllocator__malloc(allocator, 256);
  assert addr1 > 0;
  assert allocator.num_objects == initial_objects + 1;
  assert allocator.heap_used == 256;

  // 512바이트 블록 할당
  let addr2: i32 = MemoryAllocator__malloc(allocator, 512);
  assert addr2 > addr1;
  assert allocator.num_objects == initial_objects + 2;
  assert allocator.heap_used == 256 + 512;

  // 첫 번째 블록 해제
  let freed1: bool = MemoryAllocator__free(allocator, addr1);
  assert freed1 == true;
  assert allocator.num_objects == initial_objects + 1;

  // 두 번째 블록 해제
  let freed2: bool = MemoryAllocator__free(allocator, addr2);
  assert freed2 == true;
  assert allocator.num_objects == initial_objects;

  // 통계 확인
  let stats: MemoryStats = MemoryAllocator__get_stats(allocator);
  assert stats.total_allocated == 256 + 512;
  assert stats.total_freed == 256 + 512;
  assert stats.current_usage == 0;

  println("✅ T1: Allocation & Deallocation PASSED");
  return true;
}

// ============================================================================
// Test T2: GC 트리거 (Garbage Collection Trigger)
// ============================================================================

fn test_T2_gc_trigger() -> bool {
  let allocator: MemoryAllocator = MemoryAllocator__new();
  let initial_gc_runs: i32 = allocator.stats_gc_runs;

  // 큰 블록 할당 (메모리 부족 상태 유도)
  let blocks: [i32; 10];
  let i: i32 = 0;
  while i < 10 {
    let addr: i32 = MemoryAllocator__malloc(allocator, 4000);
    if addr > 0 {
      blocks[i] = addr;
    }
    i = i + 1;
  }

  // GC 실행 (임계값: 80% 이상)
  let root_addr: i32 = blocks[0];
  let gc_triggered: bool = MemoryAllocator__gc_trigger(allocator, root_addr);

  if allocator.heap_used > (44544 * 80) / 100 {
    assert gc_triggered == true;
    assert allocator.stats_gc_runs > initial_gc_runs;
  }

  println("✅ T2: GC Trigger PASSED");
  return true;
}

// ============================================================================
// Test T3: 메모리 누수 탐지 = 0 (No Memory Leaks)
// ============================================================================

fn test_T3_no_memory_leaks() -> bool {
  let allocator: MemoryAllocator = MemoryAllocator__new();

  // 객체 할당
  let addr1: i32 = MemoryAllocator__malloc(allocator, 256);
  let addr2: i32 = MemoryAllocator__malloc(allocator, 512);
  let addr3: i32 = MemoryAllocator__malloc(allocator, 128);

  // 참조 카운트 설정 (객체가 여전히 접근 가능)
  allocator.ref_count[0] = 1;
  allocator.ref_count[1] = 1;
  allocator.ref_count[2] = 1;

  // Mark phase 실행
  MemoryAllocator__mark_phase(allocator, addr1);

  // 누수 탐지
  let leak_count: i32 = MemoryAllocator__detect_leaks(allocator);
  assert leak_count == 0;

  let leak_memory: i32 = MemoryAllocator__get_leak_memory(allocator);
  assert leak_memory == 0;

  // 정리
  MemoryAllocator__free(allocator, addr1);
  MemoryAllocator__free(allocator, addr2);
  MemoryAllocator__free(allocator, addr3);

  println("✅ T3: No Memory Leaks PASSED");
  return true;
}

// ============================================================================
// Test T4: 할당 성능 (Allocation Performance)
// ============================================================================

fn test_T4_allocation_performance() -> bool {
  let allocator: MemoryAllocator = MemoryAllocator__new();

  // 100개 블록 빠르게 할당
  let i: i32 = 0;
  let addrs: [i32; 100];
  let start_time: i32 = 0;  // 시간 측정 (실제로는 시계 필요)

  while i < 100 {
    let addr: i32 = MemoryAllocator__malloc(allocator, 64);
    if addr > 0 {
      addrs[i] = addr;
    }
    i = i + 1;
  }

  // 성능 확인: 최소 90개 할당 성공
  let allocated_count: i32 = allocator.num_objects;
  assert allocated_count >= 90;

  // 정리
  i = 0;
  while i < allocated_count {
    if addrs[i] > 0 {
      MemoryAllocator__free(allocator, addrs[i]);
    }
    i = i + 1;
  }

  // 최종 상태: 모두 해제됨
  assert allocator.num_objects == 0;

  println("✅ T4: Allocation Performance PASSED");
  return true;
}

// ============================================================================
// 메인 테스트 실행
// ============================================================================

fn main() {
  println("=== FreeLang VM Phase 3: Memory Management Tests ===");
  println("");

  let passed: i32 = 0;
  let total: i32 = 4;

  // T1 실행
  if test_T1_allocation_deallocation() {
    passed = passed + 1;
  }

  // T2 실행
  if test_T2_gc_trigger() {
    passed = passed + 1;
  }

  // T3 실행
  if test_T3_no_memory_leaks() {
    passed = passed + 1;
  }

  // T4 실행
  if test_T4_allocation_performance() {
    passed = passed + 1;
  }

  println("");
  print("Results: ");
  print(passed);
  print("/");
  println(total);

  if passed == total {
    println("✅ ALL TESTS PASSED");
  } else {
    println("❌ SOME TESTS FAILED");
  }
}
